// Node.js snippet: per-tenant quota check in Azure Functions
module.exports = async function (context, req) {
  const tenant = req.headers['x-tenant-id'];
  // fetch quota from a store (e.g., Cosmos Redis cache)
  const quota = await getQuota(tenant);
  if (quota.remaining <= 0) {
    context.res = { status: 429, body: 'Quota exhausted' };
    return;
  }
  await consumeOne(tenant);
  context.res = { status: 200, body: 'ok' };
};
```

